    ('multivitaminico', 12, 'Cobre (bisglicinato de cobre)', 900, 'mcg', 'cobre', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Cobre", "forma_insumo": "Bisglicinato de cobre (CAS 13479-54-4) — insumo a adquirir", "massa_insumo_mg": 2.9978, "laudo_lote": null, "laudo_validade": null, "laudo_vencido": null, "teor_pct": 30.02, "teor_fonte": "assumido", "ativo_mg": 0.9, "unidade_ativo": "µg", "minimo": 135, "maximo": 8975.52, "pct_do_maximo": 10.03, "linha_anexo": "I·Bisglicinato de cobre; III/IV·Cobre", "status": "forma trocada", "e_sal": false, "observacao": "o insumo pesado hoje é ''Cobre Quelato 24% – Cobre Aminoácido quelato'' (NaturalPRO, lote NPT.0325/404, laudo lido por imagem em 16/09: teor de cobre 24%, sem CAS, sem nome da forma) — ''aminoácido quelato'' não é nenhuma das 5 formas do Anexo I. O rótulo já imprime ''bisglicinato de cobre''; a fórmula passa a usar o insumo que o rótulo diz."}'),
