    ('multivitaminico', 14, 'Vitamina K2 (menaquinona-7)', 120, 'mcg', 'vitamina-k', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Vitamina K", "forma_insumo": "Menaquinona-7 (CAS 2124-57-4), pré-mistura em carreador", "massa_insumo_mg": 8.1081, "laudo_lote": "PURI011426 (Gemini/Purifarma, fabricante 2003D04) — único laudo de MK-7 na máquina", "laudo_validade": "24/03/2022", "laudo_vencido": true, "teor_pct": 1.48, "teor_fonte": "laudo vencido", "ativo_mg": 0.12, "unidade_ativo": "µg", "minimo": 18, "maximo": 149.06, "pct_do_maximo": 80.5, "linha_anexo": "I·Menaquinona-7; III/IV·Vitamina K", "status": "dose ajustada", "e_sal": false, "observacao": "149 µg = 99,96% do teto (149,06) — sem folga; nova dose 120 µg (80,5%). O memorial rev02 pesa 0,150 mg tratando o insumo como ~100% puro, sem lote nem laudo; o único laudo de MK-7 da máquina mostra um pré-mix a 1,48% (subdose de ~67× se pesado como puro). Massa provisória até laudo do lote em uso."}'),
