) as v(slug, sort_order, ingredient_name, quantity, unit, ingredient_slug, metadata)
join public.formulas f on f.slug = v.slug and f.deleted_at is null
join public.ingredients i on i.slug = v.ingredient_slug and i.deleted_at is null
where not exists (
    select 1 from public.formula_compositions x
    where x.formula_id = f.id and x.deleted_at is null and x.metadata->>'fonte' = 'reformulacao_2026-09-16'
);

-- 3. campos de rotulagem da fórmula (nutritional_info é TEXT no banco vivo; o JSON da tabela vai em metadata)
update public.formulas set
    ingredients_list = 'Óxido de magnésio, antiumectante dióxido de silício (INS 551), ácido ascórbico (vitamina C), bisglicinato de zinco, acetato de DL-alfa-tocoferol (vitamina E), tetraborato de sódio decahidratado, nicotinamida (vitamina B3), colecalciferol (vitamina D3), menaquinona-7 (vitamina K2), acetato de retinol (vitamina A), D-pantotenato de cálcio (vitamina B5), bisglicinato de cobre, cloridrato de piridoxina (vitamina B6), cloridrato de tiamina (vitamina B1), riboflavina (vitamina B2), ácido fólico, picolinato de cromo, selenito de sódio, metilcobalamina (vitamina B12) e cápsula: gelatina, água purificada e corante dióxido de titânio (INS 171). NÃO CONTÉM GLÚTEN (declaração condicionada a laudo de glúten do produto acabado — ver pendência 9).',
    warnings = E'Este produto não é um medicamento.\nNão exceder a recomendação diária de consumo indicada na embalagem.\nMantenha fora do alcance de crianças.\nPúblico indicado: adultos (19 anos ou mais). Ingerir 2 cápsulas ao dia.\nEste produto não deve ser consumido por gestantes, lactantes e crianças.\nConservar o produto em local seco, fresco e arejado, ao abrigo da luz e do calor excessivo, em temperatura ambiente entre 15 °C e 30 °C. Após aberto, consumir em até 60 dias. Não consumir se o lacre de segurança estiver violado.',
